// epoll_create(size): Size must be positive (> 0), ignored since 2.6.8
int epfd_old = epoll_create(10);

if (epfd_old < 0) {
    /* Handle error (e.g., EINVAL if size=0) */
}

// epoll_create1(flags): Allows specifying behavior flags
// EPOLL_CLOEXEC ensures FD is closed across execve()
int flags = EPOLL_CLOEXEC;
int epfd_cloexec = epoll_create1(flags);

// Standard creation using epoll_create1
int epfd_new = epoll_create1(0);

// Cleanup
close(epfd_old);
close(epfd_cloexec);
close(epfd_new);
